// Week 10 V3. Run Once for All Items. SYNTHETIC FINANCE POLICY ONLY.
// Rules are deterministic. Gemini may explain, never change status or pay.
// Teaching limits: PO master and historic ledger below are fixtures, NOT live table lookups.
const poMaster = {
  'PO-501': {supplier:'ALPHA',amount:1250},
  'PO-502': {supplier:'BETA',amount:8950},
  'PO-503': {supplier:'GAMMA',amount:4700},
  'PO-505': {supplier:'DELTA',amount:24600},
};
const posted = new Set(['ALPHA|A-776']); // historical fixture; does not grow automatically
return $input.all().map(item => {
  const d=item.json;
  const team_id=String(d.team_id ?? '').trim().slice(0,20);
  const invoice_id=String(d.invoice_id ?? '').trim().toUpperCase().slice(0,60);
  const supplier=String(d.supplier ?? '').trim().toUpperCase().slice(0,60);
  const invoice_ref=String(d.invoice_ref ?? '').trim().toUpperCase().slice(0,60);
  const po_id=String(d.po_id ?? '').trim().toUpperCase().slice(0,60);
  const raw=String(d.amount_usd ?? '').trim();
  const amount=raw!=='' ? Number(raw) : NaN;
  const bank_changed=['YES','TRUE','1'].includes(String(d.bank_changed ?? 'NO').trim().toUpperCase());
  const manager_approval_required=Number.isFinite(amount) && amount>10000;
  const flags=[];
  let status='READY_FOR_HUMAN_CHECK', primary='Rules passed; human confirmation still required';
  if(!invoice_id||!supplier||!invoice_ref||!Number.isFinite(amount)||amount<=0||amount>=10000000){
    status='HOLD_INVALID_DATA';primary='Required field missing or invalid amount'; flags.push('INVALID_DATA');
  } else if(posted.has(`${supplier}|${invoice_ref}`)){
    status='HOLD_DUPLICATE';primary='Supplier and reference already in synthetic historic ledger';flags.push('HISTORIC_DUPLICATE');
  } else if(bank_changed){
    status='HOLD_BANK_CHANGE';primary='Bank details changed; independent verification required';flags.push('BANK_CHANGE');
  } else if(!po_id){
    status='REVIEW_MISSING_PO';primary='Purchase order missing';flags.push('MISSING_PO');
  } else if(!poMaster[po_id]){
    status='REVIEW_UNKNOWN_PO';primary='PO ID not in the approved synthetic PO master';flags.push('UNKNOWN_PO');
  } else if(poMaster[po_id].supplier!==supplier){
    status='REVIEW_PO_SUPPLIER';primary='Supplier does not match the PO master';flags.push('PO_SUPPLIER_MISMATCH');
  } else if(Math.abs(poMaster[po_id].amount-amount)>0.01){
    status='REVIEW_AMOUNT_MISMATCH';primary=`PO amount is $${poMaster[po_id].amount.toFixed(2)}, not the invoice amount`;flags.push('AMOUNT_MISMATCH');
  } else if(manager_approval_required){
    status='REVIEW_MANAGER';primary='Finance-manager approval required (amount > $10,000)';flags.push('HIGH_VALUE');
  }
  if(manager_approval_required&&!flags.includes('HIGH_VALUE')) flags.push('HIGH_VALUE');
  const reason=primary + (manager_approval_required && status!=='REVIEW_MANAGER' ? '; finance-manager approval also required (>$10,000)' : '');
  const control_flags=flags.join('|') || 'NONE';
  const telegram_text=`MERIDIAN | SIMULATED INVOICE TRIAGE\nTeam: ${team_id}\nInvoice: ${invoice_id}\nSupplier: ${supplier}\nAmount: $${Number.isFinite(amount)?amount.toFixed(2):'INVALID'}\nStatus: ${status}\nFlags: ${control_flags}\nReason: ${reason}\nHUMAN REVIEW REQUIRED. NO PAYMENT.`;
  return {json:{
    team_id,invoice_id,supplier,invoice_ref,
    amount_usd:Number.isFinite(amount)?amount:null,po_id,bank_changed:bank_changed?'YES':'NO',
    status,reason,control_flags,received_at:new Date().toISOString(),
    manager_approval_required,human_approval_required:true,payment_authorized:false,
    ai_can_override_status:false,telegram_text
  }};
});
